newcode='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    guides = [c for c in range(w) if any(out[r][c] for r in range(h) if r >= h - 4)]
    bands = {}
    for c in guides:
        for r in range(h):
            if out[r][c] == 0 and c > 0 and c + 1 < w and out[r][c-1] != 0 and out[r][c-1] == out[r][c+1]:
                bands.setdefault(c, []).append((r, out[r][c-1]))
    for c, rows in bands.items():
        rows.sort()
        start = 0
        for r, color in rows:
            for y in range(start, r + 1):
                out[y][c] = color
            start = r + 1
        # Connect the last completed band to the matching vertical guide below it.
        marker_rows = [r for r in range(start, h) if out[r][c] != 0]
        if marker_rows:
            marker_color = out[marker_rows[0]][c]
            for y in range(start, marker_rows[0]):
                out[y][c] = marker_color
    return out
'''
